# -*- coding: utf-8 -*-
"""train loop v1: memory is GENERATED by the net across frames (per ruling: collector does NOT store it; zero at round start;
window-start memory from the previous k frames run with CURRENT weights, detached). Smoke test again."""
import torch, torch.nn as nn, importlib.util, contextlib, io
D,KMAX,K_WIN=256,8,5
spec=importlib.util.spec_from_file_location("fn","_tools/training/net_full_v0.py"); fn=importlib.util.module_from_spec(spec)
with contextlib.redirect_stdout(io.StringIO()): spec.loader.exec_module(fn)

class AC(nn.Module):
    def __init__(self):
        super().__init__()
        self.net=fn.FullNet()
        self.mem_writer=nn.Linear(D,4*256)   # writes the 4x256 memory for the NEXT frame
        self.value=nn.Linear(D,1)
    def write_mem(self,segs,mask):
        with torch.no_grad():                # memory generation is done WITHOUT grad (input-data semantics)
            seq=torch.cat([self.net.proj[k](segs[k])+self.net.type_emb[k] for k in segs],1)
            h=self.net.trunk(seq,src_key_padding_mask=mask)[:,0]
            return self.mem_writer(h).view(-1,4,256).detach()
    def forward(self,segs,mask):
        o=self.net(segs,mask)
        seq=torch.cat([self.net.proj[k](segs[k])+self.net.type_emb[k] for k in segs],1)
        h=self.net.trunk(seq,src_key_padding_mask=mask)[:,0]
        return o,self.value(h),self.mem_writer(h)

def run_round(model,frames=20,node=64,dev="cuda"):
    mem=torch.zeros(1,4,256,device=dev)                 # round start: zero (collector stores nothing)
    tr=[]
    for t in range(frames):
        segs={"node":torch.randn(1,node,12,device=dev),"opp":torch.randn(1,1,15,device=dev),
              "bullet":torch.randn(1,8,6,device=dev),"item":torch.randn(1,4,6,device=dev),
              "global":torch.randn(1,1,38,device=dev),"mem":mem.clone()}
        m=torch.zeros(1,node+1+8+4+1+4,dtype=torch.bool,device=dev)
        tr.append((segs,m,torch.randint(0,node,(1,)),float(torch.randn(1).item())))
        mem=model.write_mem(segs,m)                      # t -> t+1 memory carried (current weights, detached)
    return tr

if __name__=="__main__":
    dev="cuda"; model=AC().to(dev); opt=torch.optim.Adam(model.parameters(),3e-4)
    p0=sum(p.detach().double().sum().item() for p in model.parameters())
    print("PARAMS_WITH_VALUE_AND_MEMWRITER %.2fM"%(sum(p.numel() for p in model.parameters())/1e6))
    rounds=[run_round(model) for _ in range(2)]; losses=[]
    for step in range(30):
        tot=torch.zeros((),device=dev); n=0
        for tr in rounds:
            for i in range(0,len(tr),K_WIN):
                win=tr[i:i+K_WIN]; L=torch.zeros((),device=dev)
                for segs,m,act,rew in win:
                    o,v,_=model(segs,m); p=o["growPtr"][0]
                    logp=torch.log(p[int(act)]+1e-8); ent=-(p*torch.log(p+1e-8)).sum()
                    adv=torch.tensor(rew,device=dev); r=torch.exp(logp-logp.detach())
                    L=L-torch.min(r*adv,torch.clamp(r,0.8,1.2)*adv)+0.01*ent+0.5*(v.mean()-adv).pow(2); n+=1
                tot=tot+L/max(1,len(win))
        tot=tot/max(1,n); opt.zero_grad(); tot.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(),0.5); opt.step(); losses.append(float(tot))
    p1=sum(p.detach().double().sum().item() for p in model.parameters())
    print("SMOKE steps=30 loss_first=%.6f loss_last=%.6f nan=%s"%(losses[0],losses[-1],any(x!=x for x in losses)))
    print("MEM_ACROSS_FRAMES ok (t->t+1 written by net, detached, zero at round start)")
    print("PARAM_SUM before=%.6f after=%.6f changed=%s"%(p0,p1,abs(p1-p0)>1e-9))
